/* ===== QR order workflow: New -> Confirm/Reject -> Preparing -> Ready -> Complete (24h list) ===== */
const ost2=o=>o.status||(o.done?"completed":"pending");
function oset(id,s){const o=S.orders.find(x=>x.id==id);if(!o)return;o.status=s;if(s=="completed"||s=="rejected"){o.done=1;o.done_t=Date.now()}sv();R()}
function ORC(id){const o=S.orders.find(x=>x.id==id);if(!o)return;const L=o.lines.map(l=>({l,f:FV(l.sku)})).filter(x=>x.f);
 if(!L.length){T("Items not found");return}
 if(L.some(x=>x.l.qty>x.f.v.qty)){T("Not enough stock for this order");return}
 const pr=x=>x.l.price!=null?+x.l.price:x.f.it.price,sb=L.reduce((s,x)=>s+pr(x)*x.l.qty,0),cs=L.reduce((s,x)=>s+x.f.it.cost*x.l.qty,0),tx=sb*S.shop.tax/100;
 const s={id:S.sales.length+1001,t:Date.now(),lines:L.map(x=>({sku:x.l.sku,n:x.f.it.name,vl:vl(x.f.v),qty:x.l.qty,price:pr(x),d:0})),sub:sb,bd:0,tax:tx,total:sb+tx,pay:o.pay_method=="bank"?"Bank":"Cash",cost:cs,profit:sb-cs,by:"QR order",ph:o.phone||"",cn:o.name||"",rv:0,sp:0,due:0};
 L.forEach(x=>{x.f.v.qty-=x.l.qty});S.sales.push(s);o.sale_id=s.id;o.total=s.total;o.status="confirmed";sv();rcpt=s;ph=s.ph;R()}
function obill(id){const o=S.orders.find(x=>x.id==id),s=o&&S.sales.find(x=>x.id==o.sale_id);if(s){rcpt=s;ph=s.ph||"";R()}}
function qrw(){const A=S.orders,now=Date.now(),by=s=>A.filter(o=>ost2(o)==s).sort((a,b)=>a.t-b.t),
 PM={cod:"\ud83d\udcb5 Cash on delivery",bank:"\ud83c\udfe6 Bank transfer \u00b7 delivery",shop:"\ud83c\udfec Shop visit"},
 row=(o,btns)=>`<div class="row" style="border-bottom:1px solid var(--bd);padding:8px 0;align-items:flex-start"><span><b>#${o.id} ${esc(o.name||"Customer")}</b> ${esc(o.phone||"")} <small style="color:var(--mu)">${new Date(o.t).toLocaleString()}</small><br>${o.lines.map(l=>esc(l.n)+" \u00d7 "+l.qty).join("<br>")}<br><small>${PM[o.pay_method]||""} ${esc(o.address||"")} ${o.total?"\u00b7 "+m(o.total):""}</small></span><span style="display:flex;gap:4px;flex-wrap:wrap;justify-content:flex-end">${btns}</span></div>`,
 sec=(t,a,f)=>`<div class="cd"><b>${t} (${a.length})</b>${a.map(f).join("")||`<p style="color:var(--mu)">\u2014</p>`}</div>`,
 bill=o=>o.sale_id?`<button onclick="obill(${o.id})">\ud83e\uddfe Bill</button>`:"",
 comp=A.filter(o=>["completed","rejected"].includes(ost2(o))&&now-(o.done_t||o.t)<864e5).sort((a,b)=>(b.done_t||b.t)-(a.done_t||a.t));
 return`<div class="cd"><div class="row"><b>\ud83d\udcf1 QR orders</b><button class="${qs?"on":""}" onclick="qs=!qs;R()">${qs?"Hide QR":"QR"}</button></div>${qs?`<div style="text-align:center;margin:12px 0"><div id="qc" style="background:#fff;padding:10px;display:inline-block"></div><br><button class="pri" onclick="QD()">\u2b07 Download QR</button><br><small>${esc(location.href.split("#")[0])}#menu</small></div>`:""}</div>
${sec("\u23f3 New orders",by("pending"),o=>row(o,`<button class="pri" onclick="ORC(${o.id})">\u2713 Confirm</button><button onclick="oset(${o.id},'rejected')">\u2715 Reject</button>`))}
${sec("\ud83d\udc68\u200d\ud83c\udf73 Preparing",by("confirmed"),o=>row(o,`<button class="pri" onclick="oset(${o.id},'ready')">\ud83d\udecd Order ready</button>${bill(o)}`))}
${sec("\ud83d\udecd Ready",by("ready"),o=>row(o,`<button class="pri" onclick="oset(${o.id},'completed')">\u2714 Complete order</button>${bill(o)}`))}
${sec("\u2714 Completed / rejected (last 24 hours)",comp,o=>row(o,`<span class="${ost2(o)=="rejected"?"wn":""}">${ost2(o)=="rejected"?"Rejected":"Completed"}</span>${bill(o)}`))}`}
